import random  # Move import to the top

class Territory:
    def __init__(self, name):
        self.name = name
        self.owner = None
        self.armies = 0

class Player:
    def __init__(self, name):
        self.name = name
        self.territories = []

    def add_territory(self, territory):
        self.territories.append(territory)
        territory.owner = self

class AIPlayer(Player):  # Correct class reference
    def __init__(self, name):
        super().__init__(name)

    def make_move(self):
        pass

class Dice:
    def roll(self):
        return random.randint(1,6)  # Random dice roll

class RiskGame:  # Correct capitalization
    def __init__(self):
        self.players = []
        self.territories = []

    def add_player(self, player):
        self.players.append(player)

    def add_territory(self, territory):
        self.territories.append(territory)

    def start_game(self):
        print("Game has started!")

# Instantiate the game correctly
game = RiskGame()
player1 = Player("Player 1")
player2 = AIPlayer("AI Player")

game.add_player(player1)
game.add_player(player2)

territory1 = Territory("Territory 1")
territory2 = Territory("Territory 2")

game.add_territory(territory1)
game.add_territory(territory2)

# Start the game
game.start_game()
